<?php require_once '../includes/auth.php';require_once '../config/koneksi.php';$daftarKelas=$conn->query("SELECT nama_kelas FROM kelas WHERE status='aktif' ORDER BY FIELD(tingkat,'VII','VIII','IX'),nama_kelas");$row=[];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$nis=trim($_POST['nis']);$nisn=trim($_POST['nisn']);$nama=trim($_POST['nama_siswa']);$jk=$_POST['jenis_kelamin'];$tempat=trim($_POST['tempat_lahir']);$tgl=$_POST['tanggal_lahir']?:null;$alamat=trim($_POST['alamat']);$kelas=trim($_POST['kelas']);$ortu=trim($_POST['nama_orang_tua']);$hp=trim($_POST['no_hp']);$status=$_POST['status'];try{$st=$conn->prepare('INSERT INTO siswa(nis,nisn,nama_siswa,jenis_kelamin,tempat_lahir,tanggal_lahir,alamat,kelas,nama_orang_tua,no_hp,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$st->bind_param('sssssssssss',$nis,$nisn,$nama,$jk,$tempat,$tgl,$alamat,$kelas,$ortu,$hp,$status);$st->execute();header('Location: index.php?success=tambah');exit;}catch(mysqli_sql_exception $ex){$error=$ex->getCode()==1062?'NIS sudah digunakan. Silakan gunakan NIS yang berbeda.':'Data gagal disimpan. Periksa kembali isian.';}$row=$_POST;}$page_title='Tambah Siswa';$active='siswa';$prefix='../';include '../includes/header.php';?>
<div class="page-heading"><div><h1>Tambah Siswa</h1><p>Lengkapi identitas peserta didik pada formulir berikut.</p></div><a href="index.php" class="btn btn-light border"><i class="bi bi-arrow-left me-1"></i>Kembali</a></div><div class="panel"><div class="panel-head"><strong><i class="bi bi-person-plus me-2 text-primary"></i>Informasi Siswa</strong></div><div class="panel-body"><?php if($error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endif;?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">NIS *</label><input name="nis" class="form-control" required maxlength="20" value="<?= e($row['nis']??'') ?>"></div><div class="col-md-6"><label class="form-label">NISN</label><input name="nisn" class="form-control" maxlength="20" value="<?= e($row['nisn']??'') ?>"></div><div class="col-md-6"><label class="form-label">Nama Lengkap *</label><input name="nama_siswa" class="form-control" required value="<?= e($row['nama_siswa']??'') ?>"></div><div class="col-md-6"><label class="form-label">Jenis Kelamin *</label><select name="jenis_kelamin" class="form-select" required><option value="">Pilih jenis kelamin</option><option value="L" <?= ($row['jenis_kelamin']??'')==='L'?'selected':'' ?>>Laki-laki</option><option value="P" <?= ($row['jenis_kelamin']??'')==='P'?'selected':'' ?>>Perempuan</option></select></div><div class="col-md-6"><label class="form-label">Kelas</label><select name="kelas" class="form-select"><option value="">Pilih kelas</option><?php $selectedKelas=$row['kelas']??''; $foundKelas=false; while($k=$daftarKelas->fetch_assoc()): if($k['nama_kelas']===$selectedKelas)$foundKelas=true; ?><option value="<?= e($k['nama_kelas']) ?>" <?= $selectedKelas===$k['nama_kelas']?'selected':'' ?>><?= e($k['nama_kelas']) ?></option><?php endwhile; if($selectedKelas!==''&&!$foundKelas):?><option value="<?= e($selectedKelas) ?>" selected><?= e($selectedKelas) ?> (data lama)</option><?php endif;?></select><div class="form-text">Tambah atau ubah pilihan melalui menu Data Kelas.</div></div><div class="col-md-6"><label class="form-label">No. HP</label><input name="no_hp" class="form-control" value="<?= e($row['no_hp']??'') ?>"></div><div class="col-md-6"><label class="form-label">Tempat Lahir</label><input name="tempat_lahir" class="form-control" value="<?= e($row['tempat_lahir']??'') ?>"></div><div class="col-md-6"><label class="form-label">Tanggal Lahir</label><input type="date" name="tanggal_lahir" class="form-control" value="<?= e($row['tanggal_lahir']??'') ?>"></div><div class="col-md-6"><label class="form-label">Nama Orang Tua/Wali</label><input name="nama_orang_tua" class="form-control" value="<?= e($row['nama_orang_tua']??'') ?>"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><option value="aktif" <?= ($row['status']??'aktif')==='aktif'?'selected':'' ?>>Aktif</option><option value="tidak_aktif" <?= ($row['status']??'')==='tidak_aktif'?'selected':'' ?>>Tidak Aktif</option></select></div><div class="col-12"><label class="form-label">Alamat</label><textarea name="alamat" class="form-control" rows="3"><?= e($row['alamat']??'') ?></textarea></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary"><i class="bi bi-check2-circle me-1"></i>Simpan Data</button><a class="btn btn-light border" href="index.php">Batal</a></div></form></div></div><?php include '../includes/footer.php';?>